CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,display_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_connections(user_id text NOT NULL REFERENCES users(id),provider text NOT NULL,encrypted_token jsonb NOT NULL,status text NOT NULL DEFAULT 'CONNECTED',PRIMARY KEY(user_id,provider));
CREATE TABLE IF NOT EXISTS campaigns(id text PRIMARY KEY,name text NOT NULL DEFAULT 'Wake Willie',paused boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaign_members(campaign_id text NOT NULL REFERENCES campaigns(id),user_id text NOT NULL REFERENCES users(id),active boolean NOT NULL DEFAULT true,ready boolean NOT NULL DEFAULT false,PRIMARY KEY(campaign_id,user_id));
CREATE TABLE IF NOT EXISTS willies(id text PRIMARY KEY,campaign_id text NOT NULL UNIQUE REFERENCES campaigns(id),version integer NOT NULL CHECK(version>=1),custodian text NOT NULL REFERENCES users(id),progress numeric NOT NULL CHECK(progress>=0 AND progress<=100));
CREATE TABLE IF NOT EXISTS willie_snapshots(campaign_id text PRIMARY KEY REFERENCES campaigns(id),version integer NOT NULL CHECK(version>=1),state jsonb NOT NULL,state_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS custodies(campaign_id text NOT NULL REFERENCES campaigns(id),version integer NOT NULL CHECK(version>=1),creator_id text NOT NULL REFERENCES users(id),PRIMARY KEY(campaign_id,version));
CREATE TABLE IF NOT EXISTS handoffs(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),source_id text NOT NULL REFERENCES users(id),destination_id text NOT NULL REFERENCES users(id),version integer NOT NULL CHECK(version>=1),status text NOT NULL CHECK(status IN('PREPARED','PROVIDER_VERIFIED','AWAITING_ACCEPTANCE','COMMITTING','COMMITTED','ABORTED','PAUSED')),expires_at bigint NOT NULL,data jsonb NOT NULL,CHECK(source_id<>destination_id));
CREATE TABLE IF NOT EXISTS handoff_evidence(provider text NOT NULL,event_id text NOT NULL,handoff_id text REFERENCES handoffs(id),occurred_at bigint NOT NULL,data jsonb NOT NULL,PRIMARY KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS passport_stamps(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),handoff_id text NOT NULL UNIQUE,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),handoff_id text NOT NULL UNIQUE,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS contributions(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS milestones(campaign_id text NOT NULL REFERENCES campaigns(id),threshold integer NOT NULL,data jsonb NOT NULL,PRIMARY KEY(campaign_id,threshold));
CREATE TABLE IF NOT EXISTS event_envelopes(provider text NOT NULL,event_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS domain_events(campaign_id text NOT NULL REFERENCES campaigns(id),id text NOT NULL,event_type text NOT NULL,occurred_at bigint NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(campaign_id,id));
CREATE TABLE IF NOT EXISTS outbox_events(id bigserial PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),domain_event_id text NOT NULL,payload jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0,delivered_at timestamptz,UNIQUE(campaign_id,domain_event_id));
CREATE TABLE IF NOT EXISTS creator_sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS overlay_sessions(token_hash text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS campaign_templates(id text NOT NULL,version integer NOT NULL CHECK(version>=1),data jsonb NOT NULL,PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS adapter_connections(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),provider text NOT NULL,config jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'DISCONNECTED');
CREATE TABLE IF NOT EXISTS brand_briefs(campaign_id text PRIMARY KEY REFERENCES campaigns(id),data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS brand_deliverables(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES campaigns(id),data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS external_platform_identities(user_id text NOT NULL REFERENCES users(id),provider text NOT NULL,provider_user_id text NOT NULL,PRIMARY KEY(provider,provider_user_id),UNIQUE(user_id,provider));
CREATE OR REPLACE FUNCTION reject_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'domain_events is append-only'; END $$;
DROP TRIGGER IF EXISTS domain_events_immutable ON domain_events;
CREATE TRIGGER domain_events_immutable BEFORE UPDATE OR DELETE ON domain_events FOR EACH ROW EXECUTE FUNCTION reject_event_mutation();
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;